#include "resource/qrx_storage_repair.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void){QrxStorageAssignment a[3];memset(a,0,sizeof(a));for(int i=0;i<3;i++){strcpy(a[i].contract_id,"c1");snprintf(a[i].provider_id,sizeof(a[i].provider_id),"p%d",i);a[i].shard_index=i;a[i].physical_bytes=1024;a[i].state=QRX_ASSIGN_ACTIVE;a[i].last_proof_epoch=5;}assert(qrx_storage_mark_degraded(&a[1],6)==0);QrxStoragePlacementCandidate c[3];memset(c,0,sizeof(c));for(int i=0;i<3;i++){snprintf(c[i].provider_id,sizeof(c[i].provider_id),"p%d",i+2);snprintf(c[i].operator_id,sizeof(c[i].operator_id),"op%d",i+2);c[i].proven_free_bytes=4096;c[i].bond_atoms=10000;c[i].availability_bps=10000;c[i].proof_success_bps=10000;c[i].performance_bps=10000;c[i].active=1;}uint8_t rnd[64]={9};QrxStorageRepairPlan p;assert(qrx_storage_plan_repair(a,3,1,c,3,1000,rnd,&p)==0);assert(strcmp(c[p.replacement_candidate_index].provider_id,"p2")!=0);QrxStorageAssignment repl;assert(qrx_storage_begin_repair(&a[1],&repl,&c[p.replacement_candidate_index],&p)==0);assert(qrx_storage_complete_repair(&a[1],&repl,0)!=0);assert(qrx_storage_complete_repair(&a[1],&repl,1)==0);assert(a[1].state==QRX_ASSIGN_REPLACED&&repl.state==QRX_ASSIGN_ACTIVE);return 0;}
